import React from 'react';

const Header = () => {
  return (
    <header className="bg-white p-4 flex justify-end items-center h-16 border-b border-gray-200 flex-shrink-0">
      <div className="w-10 h-10 bg-gray-100 border border-gray-200 rounded-full flex items-center justify-center">
         {/* Replaced with a standard, universally recognized Wi-Fi icon */}
         <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M8.111 16.555a5.5 5.5 0 017.778 0M12 20.25a.75.75 0 100-1.5.75.75 0 000 1.5z" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M4.636 12.636a9.75 9.75 0 0114.728 0" />
         </svg>
      </div>
    </header>
  );
};

export default Header;
